"use strict";
const exercises = [
 ["squat","Squat","Bacak","Ön uyluk, büyük kalça kası","Karın ve iç uyluk","Vücut ağırlığı","Kalçanı geriye ve aşağıya indir. Ayağının tamamıyla yere bastırarak doğrul."],
 ["push","Şınav","Göğüs","Büyük göğüs kası","Arka kol ve ön omuz","Vücut ağırlığı","Gövdeni düz tutarak dirseklerini bük. Zemini iterek başlangıca dön."],
 ["row","Dambıl row","Sırt","Geniş sırt kası","Pazı, arka omuz ve orta sırt","Dambıl","Kalçadan öne eğil. Dambılı kalçana doğru çekip kontrollü indir."],
 ["curl","Pazı bükme","Kol","Pazı ve brakiyalis","Ön kol","Dambıl","Üst kolunu gövdenin yanında tut. Dirseğini bükerek dambılı kaldır ve yavaşça indir."],
 ["press","Omuz presi","Omuz","Ön ve orta omuz","Arka kol","Dambıl","Dambılı omuz hizasından yukarı it. Kontrollü biçimde başlangıca dön."],
 ["bridge","Kalça köprüsü","Kalça","Büyük kalça kası","Arka uyluk ve karın","Mat","Sırtüstü yatıp dizlerini bük. Ayaklarınla yere bastırarak kalçanı kaldır ve indir."],
 ["crunch","Kısa mekik","Karın","Düz karın kası","Oblikler","Mat","Boynunu çekmeden kürek kemiklerini yerden kaldır. Kontrollü biçimde geri dön."],
 ["calf","Topuk yükseltme","Bacak","Baldır kasları","Ayak bileği çevresi","Vücut ağırlığı","Ayak önünden yükselerek topuklarını kaldır. Kısa bir duraklamayla aşağı in."],
 ["raise","Yana açış","Omuz","Orta omuz","Üst trapez ve supraspinatus","Dambıl","Dirseğini hafif bükülü tutarak kolunu yana doğru omuz hizasına kaldır ve indir."],
 ["kick","Triseps kickback","Kol","Arka kol","Arka omuz","Dambıl","Öne eğil ve üst kolunu gövdenle aynı hizada tut. Dirseğini açıp tekrar bük."]
].map(([id,name,group,primary,secondary,equipment,cue])=>({id,name,group,primary,secondary,equipment,cue}));
const media = {"squat": "data:image/gif;base64,", "push": "data:image/gif;base64,", "curl": "data:image/gif;base64,", "row": "data:image/gif;base64,", "press": "data:image/gif;base64,", "bridge": "data:image/gif;base64,", "calf": "data:image/gif;base64,", "crunch": "data:image/gif;base64,", "raise": "data:image/gif;base64,", "kick": "data:image/gif;base64,"};
const $=id=>document.getElementById(id);
const byId=id=>exercises.find(e=>e.id===id);
const key='bas.studio.v1';
let data={days:{},favorites:[]};
try{const saved=JSON.parse(localStorage.getItem(key));if(saved?.days && Array.isArray(saved.favorites))data=saved;}catch{}
let toastTimer;
function notice(message){$('notice').textContent=message;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('notice').textContent='',2500);}
function save(){try{localStorage.setItem(key,JSON.stringify(data));}catch{notice('Tarayıcı kayıt alanına erişilemiyor.');}}
function dateKey(d){return [d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-');}
const asDate=k=>new Date(k+'T12:00:00');
const format=(k,opts)=>asDate(k).toLocaleDateString('tr-TR',opts);
const today=dateKey(new Date());
let selected=today,view='studio',favoritesOnly=false,activeId;
const blankDay=()=>({items:[],note:''});
const day=()=>data.days[selected]||blankDay();
function editDay(fn){const d=data.days[selected] ||= blankDay();fn(d);if(!d.items.length&&!d.note.trim())delete data.days[selected];save();}
const sets=d=>d.items.flatMap(i=>i.sets);
$('today').textContent=format(today,{weekday:'long',day:'numeric',month:'long'}).toLocaleUpperCase('tr');
for(const group of new Set(exercises.map(e=>e.group)))$('group').add(new Option(group,group));
function renderStats(){const all=sets(day());$('stats').innerHTML=[[exercises.length,'Kütüphanede hareket'],[day().items.length,'Seçili günde hareket'],[all.filter(s=>s.done).length+'/'+all.length,'Tamamlanan set']].map(([v,l])=>'<div class="stat"><strong>'+v+'</strong><span>'+l+'</span></div>').join('');}
const normalize=s=>s.toLocaleLowerCase('tr').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replaceAll('ı','i');
function cards(){
 const query=normalize($('search').value.trim());
 const list=exercises.filter(e=>(!$('group').value||e.group===$('group').value)&&(!favoritesOnly||data.favorites.includes(e.id))&&normalize([e.name,e.group,e.equipment,e.primary].join(' ')).includes(query));
 $('count').textContent=list.length+' HAREKET';
 $('cards').innerHTML=list.map(e=>{const liked=data.favorites.includes(e.id);return '<article class="card"><button class="tile" data-open="'+e.id+'"><img alt="" src="'+media[e.id]+'"><span class="caption"><small>'+e.group.toLocaleUpperCase('tr')+'</small><strong>'+e.name+'</strong></span></button><button class="star" data-star="'+e.id+'" aria-label="'+e.name+' favori" aria-pressed="'+liked+'">'+(liked?'★':'☆')+'</button></article>';}).join('')||'<p>Bu seçimle eşleşen hareket yok.</p>';
}
function openDetail(id){const e=byId(id);activeId=id;$('name').textContent=e.name;$('tag').textContent=e.group+' / '+e.equipment;$('demo').src=media[id];$('demo').alt=e.name+' hareket döngüsü';$('info').innerHTML='<small>ANA KASLAR</small><p>'+e.primary+'</p><small>YARDIMCI KASLAR</small><p>'+e.secondary+'</p><small>UYGULAMA</small><p>'+e.cue+'</p>';$('add').textContent=format(selected,{day:'numeric',month:'long'})+' planına '+(day().items.some(i=>i.id===id)?'bir set daha ekle':'ekle');$('detail').showModal();}
$('cards').onclick=event=>{const btn=event.target.closest('button');if(!btn)return;if(btn.dataset.open)return openDetail(btn.dataset.open);const id=btn.dataset.star;data.favorites=data.favorites.includes(id)?data.favorites.filter(v=>v!==id):[...data.favorites,id];save();cards();};
$('search').oninput=cards;$('group').onchange=cards;$('fav').onclick=()=>{favoritesOnly=!favoritesOnly;$('fav').setAttribute('aria-pressed',favoritesOnly);$('fav').classList.toggle('on',favoritesOnly);cards();};
$('close').onclick=()=>$('detail').close();
const freshSet=()=>({reps:10,kg:0,done:false});
$('add').onclick=()=>{editDay(d=>{const found=d.items.find(i=>i.id===activeId);if(found)found.sets.push(freshSet());else d.items.push({id:activeId,sets:[freshSet(),freshSet(),freshSet()]});});$('detail').close();planner();notice('Günün planı güncellendi.');};
function planner(){
 $('date').value=selected;const monday=asDate(selected);monday.setDate(monday.getDate()-(monday.getDay()+6)%7);
 $('days').innerHTML=Array.from({length:7},(_,i)=>{const d=new Date(monday);d.setDate(d.getDate()+i);const k=dateKey(d);return '<button data-date="'+k+'" class="'+(k===selected?'on':'')+'">'+format(k,{weekday:'short'})+'<b>'+d.getDate()+'</b></button>';}).join('');
 const d=day();$('note').value=d.note;
 $('entries').innerHTML=d.items.map((item,i)=>'<div class="entry" data-i="'+i+'"><div class="line"><h3>'+byId(item.id).name+'</h3><button class="minor" data-action="remove">Kaldır</button></div>'+item.sets.map((s,j)=>'<div class="set" data-j="'+j+'"><small>#'+(j+1)+'</small><label>Tekrar<input type="number" data-field="reps" value="'+s.reps+'" min="1" max="999" required></label><label>Kg<input type="number" data-field="kg" value="'+s.kg+'" min="0" max="9999" step="0.01" required></label><button data-action="done" aria-label="Set tamamlandı" aria-pressed="'+s.done+'" class="'+(s.done?'on':'')+'">'+(s.done?'✓':'○')+'</button></div>').join('')+'<div class="actions"><button data-action="more">+ Set ekle</button><button data-action="less" '+(item.sets.length===1?'disabled':'')+'>Son seti sil</button></div></div>').join('')||'<div class="empty"><b>Bu günün planı boş</b>Kütüphaneden bir hareket seçerek başla.<br><button id="browse" class="minor">Hareket seç</button></div>';
 renderStats();
}
function changeDate(k){if(!/^\d{4}-\d\d-\d\d$/.test(k))return;$('date').value=selected=k;planner();}
$('date').onchange=e=>changeDate(e.target.value);$('days').onclick=e=>{const b=e.target.closest('button');if(b)changeDate(b.dataset.date);};
$('note').oninput=e=>editDay(d=>d.note=e.target.value);
$('entries').onchange=e=>{const input=e.target;if(!input.dataset.field)return;const item=day().items[+input.closest('.entry').dataset.i],s=item.sets[+input.closest('.set').dataset.j];if(!input.validity.valid){input.value=s[input.dataset.field];notice('Geçerli bir sayı gir.');return;}s[input.dataset.field]=input.valueAsNumber;save();};
$('entries').onclick=e=>{const b=e.target.closest('button');if(!b)return;if(b.id==='browse'){setView('studio');$('library').scrollIntoView();$('search').focus();return;}const i=+b.closest('.entry').dataset.i;const action=b.dataset.action;
 if(action==='remove'&&!confirm(byId(day().items[i].id).name+' ve setleri bu günden kaldırılsın mı?'))return;
 editDay(d=>{const item=d.items[i];if(action==='remove')d.items.splice(i,1);if(action==='more')item.sets.push({...item.sets.at(-1),done:false});if(action==='less'&&item.sets.length>1)item.sets.pop();if(action==='done'){const s=item.sets[+b.closest('.set').dataset.j];s.done=!s.done;}});planner();
};
function history(){const panel=$('history');panel.innerHTML='<h2>Antrenman geçmişi</h2>';const keys=Object.keys(data.days).sort().reverse();if(!keys.length)panel.insertAdjacentHTML('beforeend','<p>Kaydettiğin günler burada görünecek.</p>');for(const k of keys){const d=data.days[k],all=sets(d);const row=document.createElement('div');row.className='historyrow';row.innerHTML='<div><b>'+format(k,{day:'numeric',month:'long',year:'numeric'})+'</b><br><small>'+d.items.length+' hareket · '+all.filter(s=>s.done).length+'/'+all.length+' set tamamlandı</small></div><button>Planı aç</button>';row.querySelector('button').onclick=()=>{changeDate(k);setView('plan');};panel.append(row);}}
function setView(v){view=v;document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('on',b.dataset.view===v));$('title').textContent={studio:'Antrenman stüdyosu',plan:'Antrenman programım',history:'Kayıtlı günler'}[v];$('layout').hidden=v==='history';$('history').hidden=v!=='history';$('library').hidden=v!=='studio';$('layout').style.gridTemplateColumns=v==='plan'?'1fr':'';if(v==='history')history();if(v==='plan' && !$('addMovement')){const b=document.createElement('button');b.id='addMovement';b.className='primary wide';b.textContent='+ Hareket seç';b.onclick=()=>{setView('studio');$('search').focus();};$('days').after(b);}if($('addMovement'))$('addMovement').hidden=v!=='plan';}
document.querySelector('nav').onclick=e=>{const b=e.target.closest('button');if(b)setView(b.dataset.view);};
let remaining=60,deadline=0,interval;
function tick(){if(deadline)remaining=Math.max(0,Math.ceil((deadline-Date.now())/1000));$('clock').textContent=String(Math.floor(remaining/60)).padStart(2,'0')+':'+String(remaining%60).padStart(2,'0');if(deadline&&!remaining){clearInterval(interval);deadline=0;notice('Dinlenme süresi doldu.');}$('timerBtn').textContent=deadline?'Duraklat':'Başlat';}
function reset(){clearInterval(interval);deadline=0;remaining=Number($('duration').value);tick();}
$('duration').onchange=reset;$('reset').onclick=reset;$('timerBtn').onclick=()=>{if(deadline){tick();clearInterval(interval);deadline=0;}else{if(!remaining)remaining=Number($('duration').value);deadline=Date.now()+remaining*1000;interval=setInterval(tick,200);}tick();};
cards();planner();setView(view);
